#!/usr/bin/env bash
# Run in a clean checked-out RatelDesk tree using the SDK selected by global.json.
# NuGet changes are generated by the CLI; the three framework declarations are
# removed explicitly because dotnet package commands do not manage FrameworkReference.
set -euo pipefail
if [[ $# -lt 1 || $# -gt 2 || ( $# -eq 2 && "$2" != "--generate-only" ) ]]; then
  echo "usage: bash prepare-client-dependencies.sh <evidence-directory> [--generate-only]" >&2
  exit 64
fi
repo_root="$(git rev-parse --show-toplevel)"
cd "$repo_root"
evidence_directory="$(python3 -c 'from pathlib import Path; import sys; print(Path(sys.argv[1]).resolve())' "$1")"
mkdir -p "$evidence_directory"
exec > >(tee "$evidence_directory/preparation.log") 2>&1
dotnet --version > "$evidence_directory/sdk-version.txt"
git rev-parse HEAD > "$evidence_directory/source-revision.txt"
python3 - <<'PY'
from pathlib import Path
projects = [
    'src/Helpdesk.AgentClient/Helpdesk.AgentClient.csproj',
    'src/Helpdesk.Setup/Helpdesk.Setup.csproj',
    'src/Helpdesk.Mcp/Helpdesk.Mcp.csproj',
]
line = b'    <FrameworkReference Include="Microsoft.AspNetCore.App" />\n'
# Check every expected declaration before changing any file.
for project in projects:
    content = Path(project).read_bytes()
    if content.count(line) != 1:
        raise SystemExit(f'Expected exactly one client framework declaration: {project}')
for project in projects:
    path = Path(project)
    path.write_bytes(path.read_bytes().replace(line, b'', 1))
PY

# Use the repository's existing Microsoft.Extensions version; no CPM migration.
dotnet add src/Helpdesk.AgentClient/Helpdesk.AgentClient.csproj package Microsoft.Extensions.Configuration.Binder --version 10.0.13 --no-restore
dotnet add src/Helpdesk.Setup/Helpdesk.Setup.csproj package Microsoft.Extensions.Hosting --version 10.0.13 --no-restore
dotnet add src/Helpdesk.Mcp/Helpdesk.Mcp.csproj package Microsoft.Extensions.Hosting --version 10.0.13 --no-restore

# Both projects call Npgsql directly. Keep the existing driver version at its owners.
dotnet add src/Helpdesk.Infrastructure/Helpdesk.Infrastructure.csproj package Npgsql --version 10.0.3 --no-restore
dotnet add src/Helpdesk.API/Helpdesk.API.csproj package Npgsql --version 10.0.3 --no-restore
dotnet remove src/Helpdesk.Shared/Helpdesk.Shared.csproj package Npgsql

git diff --check
python3 - "$evidence_directory" <<'PY'
import hashlib
import json
from pathlib import Path
import shutil
import sys
out = Path(sys.argv[1])
paths = [
    'src/Helpdesk.AgentClient/Helpdesk.AgentClient.csproj',
    'src/Helpdesk.Setup/Helpdesk.Setup.csproj',
    'src/Helpdesk.Mcp/Helpdesk.Mcp.csproj',
    'src/Helpdesk.Shared/Helpdesk.Shared.csproj',
    'src/Helpdesk.Infrastructure/Helpdesk.Infrastructure.csproj',
    'src/Helpdesk.API/Helpdesk.API.csproj',
]
files = []
for path in paths:
    destination = out / 'files' / path
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(path, destination)
    files.append({'path': path, 'sha256': hashlib.sha256(destination.read_bytes()).hexdigest()})
(out / 'generated-project-files.json').write_text(json.dumps({
    'schemaVersion': 1,
    'sourceRevision': (out / 'source-revision.txt').read_text().strip(),
    'sdk': (out / 'sdk-version.txt').read_text().strip(),
    'packageGeneration': 'dotnet add/remove package; restore is a separate recorded gate',
    'files': files,
}, indent=2) + '\n', encoding='utf-8')
PY
if [[ "${2:-}" == "--generate-only" ]]; then
  exit 0
fi
# This final restore validates the exact generated package graph. Retain the
# generated files above even when restore fails; failed output is never accepted.
dotnet restore Helpdesk.sln
for target in AgentClient Setup Mcp Cli; do
  dotnet list "src/Helpdesk.$target/Helpdesk.$target.csproj" package --include-transitive --format json > "$evidence_directory/$target-packages.json"
done
